if(!exists('build_collections_episodes',mode='function'))library(creditratingsystem)
ep<-system.file('examples/retail_collections_review.R',package='creditratingsystem');if(!nzchar(ep))ep<-'creditratingsystem-r/examples/retail_collections_review.R';source(ep)
dp<-system.file('extdata/retail_collections_review.json',package='creditratingsystem');if(!nzchar(dp))dp<-'creditratingsystem-r/inst/extdata/retail_collections_review.json';d<-jsonlite::fromJSON(dp,simplifyVector=FALSE)
r<-run_retail_collections_review(d,return_artifacts=TRUE);residual<-100-1000/120
stopifnot(abs(r$remaining_claim-residual)<1e-12,abs(r$action_value$expected_net_recovery-(.25*(7/12*residual-5)+.75*20-2))<1e-10,r$no_uptake_value$expected_net_recovery==18,abs(tail(unlist(r$landmark_prediction$sustained_cure_probability),1)-2/3)<1e-12,abs(tail(unlist(r$landmark_prediction$cure_then_redefault_probability),1)-1/3)<1e-12,abs(tail(unlist(r$prior_first_cure_forecasts$fine_gray$cumulative_incidence$cure),1)-(1-exp(-1/3.75-1/2.75)))<1e-12,r$cure_targets[[1]]$cure_at=='2024-03-16',r$cure_targets[[1]]$redefault_at=='2024-04-15',r$observed_episodes$episodes[[2]]$previous_episode_id==r$observed_episodes$episodes[[1]]$episode_id,all(vapply(r$missing_probation_targets,function(t)is.null(t$cure_label),TRUE)))
a<-r$action_history$rows[[1]];stopifnot(!a$accepted,!a$performed,!a$causal_effect_identified,is.null(d$open_workout$episode$resolution_date))
y<-expected_collections_value(list(r$raw_artifacts$action_value_input),unlist(d$discount_factors),ead=r$remaining_claim,currency='EUR',period_end_dates=unlist(d$period_end_dates))$value[[1]];stopifnot(identical(content_fingerprint(y)$value,content_fingerprint(r$action_value)$value))
x<-d;x$training$known_at<-'2025-01-01';stopifnot(inherits(try(run_retail_collections_review(x),silent=TRUE),'try-error'));x<-d;x$valuation_date<-'2024-03-29';x$action_history$actions[[1]]$occurred_at<-'2024-03-29';x$action_history$actions[[1]]$known_at<-'2024-03-29';stopifnot(inherits(try(run_retail_collections_review(x),silent=TRUE),'try-error'))
